[{"order":1,"type":"heading","text":"Monitoring and Logging in JavaScript"},{"order":2,"type":"paragraph","text":"Effective monitoring and logging are crucial for maintaining and debugging JavaScript applications, whether they run in the browser or on a server (Node.js). They provide insights into application behavior, performance bottlenecks, and potential errors."},{"order":3,"type":"subheading","text":"Browser-Side Logging"},{"order":4,"type":"paragraph","text":"The simplest form of logging in the browser involves using the `console` object. This object provides several methods for outputting information to the browser's developer console."},{"order":5,"type":"code","text":"// Basic logging
console.log('This is a log message');
console.info('This is an informational message');
console.warn('This is a warning message');
console.error('This is an error message');

// Logging variables
let name = 'John';
let age = 30;
console.log('Name:', name, 'Age:', age);

// Logging objects
let user = { name: 'Jane', city: 'New York' };
console.log('User:', user);

// Using console.table for tabular data
let data = [{name: 'Alice', age: 25}, {name: 'Bob', age: 30}];
console.table(data);"},{"order":6,"type":"paragraph","text":"The `console.table()` method is particularly useful for displaying arrays of objects in a tabular format, making it easier to read and analyze data."},{"order":7,"type":"subheading","text":"Server-Side Logging (Node.js)"},{"order":8,"type":"paragraph","text":"In Node.js, you can use the `console` object similarly to the browser. However, for more robust logging, consider using dedicated logging libraries like Winston or Morgan."},{"order":9,"type":"code","text":"// Using console.log in Node.js
console.log('Server started');"},{"order":10,"type":"subheading","text":"Winston Logging Library"},{"order":11,"type":"paragraph","text":"Winston is a popular logging library for Node.js that provides features like log levels, transports (e.g., console, file), and formatting."},{"order":12,"type":"code","text":"// Installation: npm install winston

const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

logger.info('This is an info message', { meta: { userId: 123 } });
logger.warn('This is a warning message');
logger.error('This is an error message');"},{"order":13,"type":"paragraph","text":"This example configures Winston to log messages to both the console and a file named `combined.log`. It also includes timestamps and formats the logs as JSON."},{"order":14,"type":"subheading","text":"Morgan Logging Middleware"},{"order":15,"type":"paragraph","text":"Morgan is an HTTP request logger middleware for Node.js. It's commonly used with Express.js to automatically log incoming requests."},{"order":16,"type":"code","text":"// Installation: npm install morgan

const express = require('express');
const morgan = require('morgan');

const app = express();

// Log all HTTP requests to the console
app.use(morgan('dev'));

// Or log to a file
const fs = require('fs');
const path = require('path');
const accessLogStream = fs.createWriteStream(path.join(__dirname, 'access.log'), { flags: 'a' });
app.use(morgan('combined', { stream: accessLogStream }));

app.get('/', (req, res) => {
  res.send('Hello World!');
});

app.listen(3000, () => {
  console.log('Server listening on port 3000');
});"},{"order":17,"type":"paragraph","text":"Morgan provides various predefined formats (e.g., 'dev', 'combined', 'common') and allows you to define custom formats.  The example shows logging to both the console and a file."},{"order":18,"type":"subheading","text":"Error Tracking and Monitoring Services"},{"order":19,"type":"paragraph","text":"For more advanced monitoring and error tracking, consider using services like Sentry, Rollbar, or Bugsnag. These services provide features like error aggregation, stack trace analysis, and user context, making it easier to identify and fix issues in your applications."},{"order":20,"type":"bullet_point","text":"Sentry: Captures errors and provides detailed reports."},{"order":21,"type":"bullet_point","text":"Rollbar: Similar to Sentry, focuses on error tracking and reporting."},{"order":22,"type":"bullet_point","text":"Bugsnag: Another error tracking service with real-time error monitoring."},{"order":23,"type":"paragraph","text":"These services typically involve installing a client-side library in your JavaScript application and configuring it to send error reports to their servers. They often provide integrations with popular frameworks and libraries."},{"order":24,"type":"subheading","text":"Custom Monitoring"},{"order":25,"type":"paragraph","text":"You can also implement custom monitoring solutions using JavaScript. This might involve tracking specific events, measuring performance metrics, or sending data to a custom monitoring dashboard."},{"order":26,"type":"code","text":"// Example of custom performance monitoring
let startTime = performance.now();

// Code to be measured
for (let i = 0; i < 1000000; i++) {
  // Some operation
}

let endTime = performance.now();
let duration = endTime - startTime;
console.log('Operation took ' + duration + ' milliseconds');"},{"order":27,"type":"paragraph","text":"The `performance.now()` method provides high-resolution timestamps that can be used to measure the execution time of code blocks."},{"order":28,"type":"subheading","text":"Best Practices"},{"order":29,"type":"bullet_point","text":"Use appropriate log levels (e.g., debug, info, warn, error) to categorize log messages."},{"order":30,"type":"bullet_point","text":"Include relevant context in log messages (e.g., user ID, request ID, timestamp)."},{"order":31,"type":"bullet_point","text":"Avoid logging sensitive information (e.g., passwords, API keys)."},{"order":32,"type":"bullet_point","text":"Implement centralized logging for easier analysis and troubleshooting."},{"order":33,"type":"bullet_point","text":"Use structured logging formats (e.g., JSON) for easier parsing and querying."},{"order":34,"type":"paragraph","text":"By following these best practices, you can create a robust monitoring and logging system that helps you maintain and debug your JavaScript applications effectively."}]
